import Link from "next/link";
import Begriff from "@/components/Portal/Bedienung/Begriff";
import { MessageSquareText } from "lucide-react";
import FlaecheFormular from "@/components/Portal/FlaecheFormular";
import Checkliste from "@/components/Portal/Checkliste";
import { AktivitaetsFeed, AufgabenKarte } from "@/components/Portal/ObjektBackoffice";
import StatusAktionen from "@/components/Portal/StatusAktionen";
import NachrichtenThread from "@/components/Portal/NachrichtenThread";
import KiFlaeche from "@/components/Portal/Ki/KiFlaeche";
import Zuweisung from "@/components/Portal/Zuweisung";
import { DokumentListe, DokumentUpload } from "@/components/Portal/Dokumente";
import { Angaben, Hinweis, Karte, SeitenKopf, StatusBadge, Stepper, Timeline } from "@/components/Portal/ui";
import { portalNutzer, laden, istAdmin } from "@/lib/plattform/server/seite";
import { backend } from "@/lib/plattform/backend";
import { FLAECHE_NUTZUNG, LAENDER } from "@/lib/plattform/konstanten";
import { statusInfo } from "@/lib/plattform/prozesse";
import { datumZeit, ha } from "@/lib/plattform/format";
import { AGRI } from "@/lib/invest/markt";
// Fachprüfung Flächen: Pipeline-Erklärung, Prüfhinweise, Fachangaben, Angebotsbogen
import { Angebotsbogen, FachAngaben, FachPruefungListe, PipelineHinweis, begriffeFuer } from "@/components/Portal/Flaeche/Fachanzeige";
import { pachtVorschlag } from "@/lib/plattform/flaecheFach";
import { fachBackend } from "@/lib/plattform/backend/kommune";
import GrundbuchAmObjekt from "@/components/Portal/Closing/GrundbuchAmObjekt"; // Grundbuch & Closing

export const metadata = { title: "Fläche" };

export default async function Flaeche({ params }) {
  const { id } = await params;
  const n = await portalNutzer();
  const b = backend();
  await fachBackend().fachDemoBereit(); // Demo: Fachangaben der Demo-Flächen einmalig ergänzen (Frappe: nichts)
  const f = await laden(() => b.flaeche(n, id));
  const admin = istAdmin(n);
  const eigen = f.nutzerId === n.id || f.meinZugriff === "schreiben"; // Team: Teamrolle ≥ Mitglied bearbeitet wie der Eigentümer
  const [thread, dokumente, adminKonten] = await Promise.all([
    b.nachrichten(n, "flaeche", id),
    b.dokumente(n, { bezugArt: "flaeche", bezugId: id }),
    admin ? b.adminKonten(n) : [],
  ]);
  const bearbeitbar = admin || (eigen && ["entwurf", "eingegangen"].includes(f.status));

  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow={admin && !eigen ? "Fläche · Backoffice" : "Fläche"}
        titel={f.bezeichnung}
        text={[ha(f.ha), FLAECHE_NUTZUNG[f.nutzung], [f.plz, f.ort].filter(Boolean).join(" "), LAENDER[f.land]].filter(Boolean).join(" · ")}
        aktionen={<StatusBadge art="flaeche" status={f.status} className="text-[13px]" />}
      />

      <Karte>
        <Stepper art="flaeche" status={f.status} />
        <p className="mt-4 text-[14.5px] leading-relaxed text-ink-600">{statusInfo("flaeche", f.status).text}</p>
        {f.status === "abgelehnt" && f.ablehnGrund && <p className="mt-2 text-[14.5px] font-medium text-ink-800">Begründung: {f.ablehnGrund}</p>}
        <PipelineHinweis status={f.status} land={f.land} className="mt-5" />
      </Karte>

      <Angebotsbogen
        flaeche={f}
        aktionen={
          eigen && f.status === "pachtangebot" ? (
            <>
              <StatusAktionen art="flaeche" id={f.id} status={f.status} als="eigentuemer" />
              <Link href="#nachrichten" className="inline-flex items-center gap-2 text-[14px] font-semibold text-white/80 hover:text-white">
                <MessageSquareText aria-hidden="true" className="h-4 w-4" /> Rückfrage stellen
              </Link>
            </>
          ) : null
        }
      />

      <div className="grid gap-6 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
        <div className="min-w-0 space-y-6">
          {eigen && <KiFlaeche flaecheId={f.id} agri={!!f.agri} />}

          <Karte titel="Nachrichten" id="nachrichten" untertitel="Rückfragen und Abstimmung zu dieser Fläche">
            <NachrichtenThread bezugArt="flaeche" bezugId={f.id} nachrichten={thread.nachrichten} />
          </Karte>

          <Karte titel="Angaben zur Fläche">
            <Angaben
              items={[
                { label: "Bundesland / Kanton", wert: f.bundesland },
                { label: "Größe", wert: ha(f.ha) },
                { label: "Nutzung", wert: FLAECHE_NUTZUNG[f.nutzung] },
                { label: "Agri-PV gewünscht", wert: f.agri ? "Ja" : "Nein" },
                { label: "Hinweise", wert: f.hinweise, breit: true },
                { label: "Angelegt", wert: datumZeit(f.erstelltAm) },
                admin && f.eigentuemer ? { label: "Eigentümer (Konto)", wert: `${f.eigentuemer.vorname} ${f.eigentuemer.nachname} · ${f.eigentuemer.email}` } : null,
                admin && f.vorgangId ? { label: "Aus Anfrage", wert: <Link className="text-ov-700 underline" href={`/portal/admin/vorgaenge/${f.vorgangId}`}>{f.vorgangId}</Link> } : null,
              ]}
            />
            <div className="mt-5 border-t border-ink-100 pt-5">
              <FachAngaben flaeche={f} />
            </div>
            {bearbeitbar && (
              <details className="group mt-6 rounded-2xl bg-sand-50 ring-1 ring-ink-200/70" open={f.status === "entwurf" && eigen}>
                <summary className="cursor-pointer list-none px-4 py-3 text-[14.5px] font-semibold text-ov-700 [&::-webkit-details-marker]:hidden">
                  {f.status === "entwurf" ? "Angaben vervollständigen & einreichen" : "Angaben bearbeiten"}
                </summary>
                <div className="border-t border-ink-200/70 p-4 md:p-5">
                  <FlaecheFormular flaeche={f} begriffe={begriffeFuer()} />
                </div>
              </details>
            )}
          </Karte>
        </div>

        <div className="min-w-0 space-y-6">
          {(admin || eigen) && (
            <Karte titel={admin && !eigen ? "Bearbeitung (Backoffice)" : "Aktionen"}>
              {admin && (
                <div className="mb-5">
                  <Zuweisung art="flaeche" id={f.id} zustaendigId={f.zustaendigId} konten={adminKonten} />
                </div>
              )}
              {eigen && f.status === "pachtangebot" && <p className="text-[14px] leading-relaxed text-ink-600">Bitte prüfen Sie das Pachtangebot oben: annehmen oder Rückfrage per Nachricht stellen.</p>}
              {eigen && f.status !== "pachtangebot" && <StatusAktionen art="flaeche" id={f.id} status={f.status} als="eigentuemer" leerText={admin ? undefined : "Aktuell ist nichts von Ihnen zu tun – wir melden uns."} />}
              {admin && (
                <StatusAktionen
                  art="flaeche"
                  id={f.id}
                  status={f.status}
                  als="admin"
                  kontext={{ pachtVorschlag: pachtVorschlag(f) }}
                  leerText="Keine weiteren Schritte vorgesehen."
                />
              )}
              {!admin && f.zustaendig && <p className="mt-4 text-[13.5px] text-ink-500">Ihr Ansprechpartner: <span className="font-semibold text-ink-800">{f.zustaendig.vorname} {f.zustaendig.nachname}</span></p>}
            </Karte>
          )}

          {(admin || eigen) && (
            <Karte titel="Fachliche Vorprüfung" untertitel="Einordnung Ihrer Angaben mit Ampel">
              <FachPruefungListe flaeche={f} />
            </Karte>
          )}

          <Karte titel="Verlauf">
            <Timeline art="flaeche" verlauf={f.statusVerlauf} />
          </Karte>

          <GrundbuchAmObjekt nutzer={n} bezugArt="flaeche" bezugId={f.id} />{/* Grundbuch & Closing: Dienstbarkeit */}

          {(admin || eigen) && (
            <Karte titel="Unterlagen zur Fläche" untertitel="Damit wir schnell und verbindlich prüfen können">
              <Checkliste checkliste={f.checkliste} bezugArt="flaeche" bezugId={f.id} kategorie="allgemein" kategorieJePunkt={{ flurkarte: "plan" }} darfHochladen={admin || eigen} />
            </Karte>
          )}

          <Karte titel="Dokumente" untertitel="Grundbuchauszug, Lageplan, Pachtangebot">
            <DokumentListe dokumente={dokumente} nutzerId={n.id} admin={admin} leerText="Noch keine Dokumente." />
            <div className="mt-4">
              <DokumentUpload bezugArt="flaeche" bezugId={f.id} kategorien={admin ? ["vertrag", "plan", "allgemein"] : ["allgemein", "plan"]} />
            </div>
          </Karte>

          {admin && <AufgabenKarte nutzer={n} bezugArt="flaeche" bezugId={f.id} />}
          {admin && <AktivitaetsFeed nutzer={n} objektId={f.id} weitereIds={f.vorgangId ? [f.vorgangId] : []} />}

          {f.agri && (
            <Hinweis ton="ok" titel="Agri-PV">
              Die landwirtschaftliche Nutzung bleibt Hauptnutzung. Wir planen nach <Begriff id="din-spec-91434">DIN SPEC 91434</Begriff>: Der landwirtschaftliche Ertrag muss mindestens {Math.round(AGRI.mindestErtrag * 100)} % des Referenzertrags erreichen; in Deutschland bleiben {Math.round(AGRI.gapFoerderfaehig * 100)} % der Fläche GAP-förderfähig.
            </Hinweis>
          )}
        </div>
      </div>
    </div>
  );
}
import { Plus } from "lucide-react";
import Button from "@/components/ui/Button";
import { SeitenKopf } from "@/components/Portal/ui";
import FlaechenListe from "@/components/Portal/Bedienung/Liste/FlaechenListe";
import { portalNutzer } from "@/lib/plattform/server/seite";
import { backend } from "@/lib/plattform/backend";
import { ha } from "@/lib/plattform/format";
import { fmt } from "@/lib/rechner/annahmen";
import { PROVISION } from "@/lib/invest/markt";

export const metadata = { title: "Flächen" };

export default async function Flaechen() {
  const n = await portalNutzer({ rollen: ["flaeche", "landwirt"] });
  const flaechen = await backend().flaechen(n);
  const summe = flaechen.reduce((s, f) => s + (f.ha || 0), 0);

  return (
    <div>
      <SeitenKopf
        eyebrow="Flächen"
        titel="Meine Flächen"
        text={`Von der Vorprüfung bis zum Betrieb: Hier sehen Sie für jede Fläche, wo sie steht. Die Prüfung ist ${PROVISION.flaeche.text}.`}
        aktionen={<Button href="/portal/flaechen/neu" icon={Plus}>Fläche hinzufügen</Button>}
      />
      {flaechen.length > 0 && (
        <p className="mb-4 text-[14px] text-ink-600">
          <span className="ov-num font-semibold text-ink-900">{fmt(flaechen.length)}</span> {flaechen.length === 1 ? "Fläche" : "Flächen"} mit zusammen <span className="ov-num font-semibold text-ink-900">{ha(summe)}</span>
        </p>
      )}
      <FlaechenListe flaechen={flaechen} jetzt={Date.now()} />
    </div>
  );
}
// GET  /api/portal/flaechen – eigene Flächen
// POST /api/portal/flaechen – Fläche anlegen { bezeichnung, land, bundesland, plz, ort, gemarkung, flurstuecke[], ha, nutzung, agri, eigentum, hinweise, einreichen? }
import { route } from "@/lib/plattform/server/route";

const ROLLEN = ["flaeche", "landwirt"];

export const GET = route({ rollen: ROLLEN }, async ({ backend, nutzer }) => ({ ok: true, flaechen: await backend.flaechen(nutzer) }));

export const POST = route({ rollen: ROLLEN }, async ({ backend, nutzer, body, ip }) => ({
  ok: true,
  flaeche: await backend.flaecheAnlegen(nutzer, body, { ip }),
}));
// GET   /api/portal/flaechen/[id] – eine Fläche (Eigentümer oder Admin)
// PATCH /api/portal/flaechen/[id] – bearbeiten (Eigentümer nur in Entwurf/Eingegangen)
import { route } from "@/lib/plattform/server/route";

export const GET = route({}, async ({ backend, nutzer, params }) => ({ ok: true, flaeche: await backend.flaeche(nutzer, params.id) }));

export const PATCH = route({}, async ({ backend, nutzer, params, body }) => ({ ok: true, flaeche: await backend.flaecheAendern(nutzer, params.id, body) }));

import Link from "next/link";
import { BadgeEuro, CalendarClock, FileText, Info, ReceiptText, ShieldAlert, SunMedium, Wallet } from "lucide-react";
import Button from "@/components/ui/Button";
import { Karte, Leer, SeitenKopf } from "@/components/Portal/ui";
import { Wert } from "@/components/Portal/Anlagen/teile";
import { BelegListe, MonatsDiagramm, euro, euro0, kwh, tag, zeitraum } from "@/components/Portal/Finanzen/teile";
import { cn } from "@/components/ui/cn";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { finanzenBackend } from "@/lib/plattform/backend/finanzen";

export const metadata = { title: "Abrechnungen" };

function JahrWahl({ jahre, jahr }) {
  if (jahre.length < 2) return null;
  return (
    <nav aria-label="Jahr wählen" className="-mx-4 mb-6 overflow-x-auto px-4 ov-no-scrollbar md:mx-0 md:px-0">
      <ul className="flex min-w-max gap-1.5 rounded-full bg-white p-1.5 ring-1 ring-ink-200/70 md:inline-flex md:min-w-0">
        {jahre.map((j) => (
          <li key={j}>
            <Link href={`/portal/abrechnungen?jahr=${j}`} scroll={false} aria-current={j === jahr ? "page" : undefined} className={cn("ov-num inline-flex h-9 items-center rounded-full px-4 text-[14px] font-semibold", j === jahr ? "bg-navy-900 text-white" : "text-ink-700 hover:bg-ink-50")}>
              {j}
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
}

function Vertrag({ v }) {
  return (
    <li className="rounded-3xl bg-white p-5 ring-1 ring-ink-200/70 md:p-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="font-display text-[17px] font-bold text-ink-900">{v.bezeichnung}</p>
          <p className="text-[13px] text-ink-500">{v.modellLabel} · {v.objektLabel}{v.flaecheHa ? ` · ${v.flaecheHa.toLocaleString("de-DE")} ha` : ""} · {v.land}</p>
        </div>
        {v.jahrespachtAktuell !== null && (
          <div className="text-right">
            <p className="text-[12px] text-ink-500">Jahrespacht aktuell</p>
            <p className="ov-num font-display text-[20px] font-extrabold text-ink-900">{euro(v.jahrespachtAktuell)}</p>
          </div>
        )}
      </div>
      <dl className="mt-4 grid grid-cols-2 gap-x-4 gap-y-2 text-[13.5px] sm:grid-cols-4">
        <div><dt className="text-ink-500">Pachtbeginn</dt><dd className="font-semibold text-ink-900">{v.beginn ? tag(v.beginn) : `mit ${v.beginnLabel || "Baubeginn"}`}</dd></div>
        <div><dt className="text-ink-500">Laufzeit</dt><dd className="font-semibold text-ink-900">{v.laufzeitJahre} Jahre{v.ende ? ` (bis ${tag(v.ende)})` : ""}</dd></div>
        <div><dt className="text-ink-500">Zahlung</dt><dd className="font-semibold text-ink-900">{v.faelligkeitLabel}, {v.zahlweise === "vorschuessig" ? "im Voraus" : "im Nachhinein"}</dd></div>
        <div>
          <dt className="text-ink-500">Nächste Zahlung</dt>
          <dd className="font-semibold text-ink-900">{v.naechsteZahlung ? `${tag(v.naechsteZahlung.faelligAm)} · ${v.naechsteZahlung.mindestens ? "mind. " : ""}${euro(v.naechsteZahlung.betrag)}` : "–"}</dd>
        </div>
      </dl>
      {v.erklaerung?.length > 0 && (
        <details className="group mt-4 rounded-2xl bg-sand-100/70 p-4">
          <summary className="flex cursor-pointer list-none items-center gap-2 text-[14px] font-semibold text-ink-900">
            <Info aria-hidden="true" className="h-4 w-4 text-ov-600" />
            So wird Ihre Pacht berechnet
            <span aria-hidden="true" className="ml-auto text-ink-400 transition-transform group-open:rotate-90">›</span>
          </summary>
          <ul className="mt-3 space-y-1.5 text-[13.5px] leading-relaxed text-ink-700">
            {v.erklaerung.map((z, i) => <li key={i}>{z}</li>)}
            {v.naechsteZahlung?.phase === "reservierung" && <li>Bis zum Pachtbeginn erhalten Sie die vereinbarte Reservierungsprämie.</li>}
          </ul>
        </details>
      )}
    </li>
  );
}

export default async function AbrechnungenSeite({ searchParams }) {
  const n = await portalNutzer();
  const sp = (await searchParams) || {};
  const d = await laden(() => finanzenBackend().meineAbrechnungen(n, { jahr: sp.jahr }));
  const { pacht, contracting, provision, jahr } = d;
  const nichts = !pacht.sichtbar && !contracting.sichtbar && !provision.sichtbar;
  const imJahr = (liste) => liste.filter((b) => String(b.zeitraum?.von || "").startsWith(String(jahr)));

  return (
    <>
      <SeitenKopf
        eyebrow="Portal · Finanzen"
        titel="Abrechnungen"
        text="Pachtabrechnungen, Rechnungen und Zahlungen an einem Ort – jede Abrechnung als PDF, mit Status und Erläuterung."
      />
      {nichts ? (
        <Leer icon={ReceiptText} titel="Noch keine Abrechnungen" text="Sobald ein Pachtvertrag läuft, eine Contracting-Anlage abgerechnet oder eine Provision fällig wird, erscheinen die Belege hier – mit PDF und Zahlungsstatus." aktion={<Button href="/portal" size="sm" variant="secondary">Zur Übersicht</Button>} />
      ) : (
        <>
          <JahrWahl jahre={d.jahre} jahr={jahr} />

          {pacht.sichtbar && (
            <section aria-labelledby="pacht" className="mb-10">
              <h2 id="pacht" className="mb-4 font-display text-[20px] font-bold text-ink-900">Pacht</h2>
              <div className="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4">
                <Wert ton="dunkel" icon={Wallet} label={`Pacht ${jahr}`} wert={euro0(pacht.jahr.brutto)} hinweis={`${pacht.jahr.anzahl} Gutschriften`} />
                <Wert icon={BadgeEuro} label="Ausgezahlt" wert={euro0(pacht.jahr.bezahlt)} />
                <Wert icon={FileText} label="Offen" wert={euro0(pacht.jahr.offen)} />
                <Wert icon={CalendarClock} label="Nächste Zahlung" wert={pacht.naechsteZahlung ? tag(pacht.naechsteZahlung.faelligAm) : "–"} hinweis={pacht.naechsteZahlung ? `${pacht.naechsteZahlung.mindestens ? "mind. " : ""}${euro(pacht.naechsteZahlung.betrag)} · ${pacht.naechsteZahlung.vertrag}` : ""} />
              </div>
              {pacht.auszahlung && !pacht.auszahlung.ok && (
                <div role="status" className="mb-5 flex flex-col gap-3 rounded-3xl bg-sun-300/20 p-5 ring-1 ring-sun-400/50 sm:flex-row sm:items-center">
                  <ShieldAlert aria-hidden="true" className="h-6 w-6 shrink-0 text-ink-900" />
                  <p className="text-[14.5px] leading-relaxed text-ink-900">
                    <strong>Auszahlung vorbereitet, aber noch gesperrt.</strong> {pacht.auszahlung.hinweis} Ihre Gutschriften bleiben erhalten und werden danach überwiesen.
                  </p>
                  <Button href="/portal/verifizierung" size="sm" variant="navy" className="sm:ml-auto">Zur Verifizierung</Button>
                </div>
              )}
              {pacht.vertraege.length > 0 && <ul className="mb-5 grid gap-4 xl:grid-cols-2">{pacht.vertraege.map((v) => <Vertrag key={v.id} v={v} />)}</ul>}
              <Karte titel={`Gutschriften ${jahr}`} untertitel={pacht.auszahlung?.ibanMaskiert ? `Auszahlung auf ${pacht.auszahlung.ibanMaskiert}` : "Pachtabrechnungen als Gutschrift"} innen="p-0">
                <BelegListe belege={imJahr(pacht.belege)} leer={`Keine Gutschriften für ${jahr}.`} betragLabel="Auszahlung" />
              </Karte>
            </section>
          )}

          {contracting.sichtbar && (
            <section aria-labelledby="contracting" className="mb-10">
              <h2 id="contracting" className="mb-4 font-display text-[20px] font-bold text-ink-900">Contracting-Strom</h2>
              <div className="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4">
                <Wert ton="dunkel" icon={SunMedium} label={`PV-Strom ${jahr}`} wert={kwh(contracting.monate.reduce((s, m) => s + m.kwh, 0))} hinweis="aus geeichten Zählerständen" />
                <Wert icon={ReceiptText} label="Rechnungen" wert={euro0(contracting.jahr.brutto)} hinweis={`${contracting.jahr.anzahl} Rechnungen`} />
                <Wert icon={BadgeEuro} label="Bezahlt" wert={euro0(contracting.jahr.bezahlt)} />
                <Wert icon={FileText} label="Offen" wert={euro0(contracting.jahr.offen)} />
              </div>
              <div className="mb-5 grid gap-5 xl:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
                <Karte titel="Verbrauch je Monat" untertitel="Gelieferter PV-Strom aller Anlagen">
                  <MonatsDiagramm monate={contracting.monate} />
                </Karte>
                <Karte titel="Monatsübersicht" innen="p-0">
                  <ul className="divide-y divide-ink-100">
                    {contracting.monate.length ? [...contracting.monate].reverse().map((m) => (
                      <li key={m.monat} className="flex items-center justify-between gap-3 px-5 py-3 text-[14px] md:px-6">
                        <span className="font-semibold text-ink-900">{m.monat.slice(5)}/{m.monat.slice(0, 4)}</span>
                        <span className="text-ink-600">{kwh(m.kwh)} · {m.anlagen} Anlage{m.anlagen === 1 ? "" : "n"}</span>
                        <span className="ov-num font-semibold text-ink-900">{euro(m.brutto)}</span>
                      </li>
                    )) : <li className="px-6 py-6 text-[14px] text-ink-500">Keine Abrechnungen in {jahr}.</li>}
                  </ul>
                </Karte>
              </div>
              <Karte titel={`Rechnungen ${jahr}`} untertitel="Je Anlage und Monat: Arbeitspreis × gelieferte kWh + Grundgebühr" innen="p-0">
                <BelegListe belege={imJahr(contracting.belege)} leer={`Keine Rechnungen für ${jahr}.`} />
              </Karte>
              <p className="mt-3 text-[13px] text-ink-500">Die Live-Werte Ihrer Anlagen finden Sie unter <Link href="/portal/anlagen" className="font-semibold text-ov-700 hover:text-ov-800">Meine Anlagen</Link>. Abgerechnet wird ausschließlich über die geeichten Zähler.</p>
            </section>
          )}

