export const kurzKonto = (u) => (u ? { id: u.id, vorname: u.vorname, nachname: u.nachname, email: u.email, firma: u.firma || "" } : null);
export const nutzerVon = (db, id) => (id ? db.nutzer.find((u) => u.id === id) || null : null);
export const nameVon = (db, id) => {
