// GET /api/portal/pachtakte – eigene Pachtakten: Vertrag, Fristen, Anliegen, Rückbau/Sicherheit, Agri-PV-Nachweise,
// Jahre mit Jahresbescheinigung. Nur eigene Pachtverträge (Backend prüft Eigentum).
import { route } from "@/lib/plattform/server/route";
import { pachtakteBackend } from "@/lib/plattform/backend/pachtakte";

export const GET = route({ rollen: ["flaeche", "landwirt"] }, async ({ nutzer }) => ({ ok: true, ...(await pachtakteBackend().meinePachtakte(nutzer)) }));
EOF
cat > $B/anliegen/route.js <<'EOF'
// POST /api/portal/pachtakte/anliegen – Anliegen zum eigenen Pachtvertrag { vertragId, art, daten }
//   art: kuendigung | eigentuemerwechsel | erbfall | zahlungsaufteilung | verlaengerung (Positivliste: lib/plattform/pachtakte.js)
import { route } from "@/lib/plattform/server/route";
import { pachtakteBackend } from "@/lib/plattform/backend/pachtakte";

export const POST = route({ rollen: ["flaeche", "landwirt"], limit: "formular" }, async ({ nutzer, body, ip }) => ({
  ok: true,
  anliegen: await pachtakteBackend().anliegenAnlegen(nutzer, { vertragId: body.vertragId, art: body.art, daten: body.daten || {} }, { ip }),
}));
EOF
cat > "$B/anliegen/[id]/route.js" <<'EOF'
// POST /api/portal/pachtakte/anliegen/[id] – Eigentümer: auf Rückfrage antworten { nach: "eingereicht", kommentar }
// oder zurückziehen { nach: "zurueckgezogen" }. Backoffice-Schritte: /api/admin/pachtakte/anliegen/[id].
import { route } from "@/lib/plattform/server/route";
import { pachtakteBackend } from "@/lib/plattform/backend/pachtakte";
import { PlattformFehler } from "@/lib/plattform/fehler";

export const POST = route({ rollen: ["flaeche", "landwirt"] }, async ({ nutzer, params, body, ip }) => {
  if (!["eingereicht", "zurueckgezogen"].includes(body.nach)) throw new PlattformFehler(422, "Dieser Schritt ist hier nicht möglich.");
  return { ok: true, anliegen: await pachtakteBackend().anliegenAktion(nutzer, params.id, { nach: body.nach, kommentar: body.kommentar }, { ip }) };
});
EOF
cat > $B/agri/route.js <<'EOF'
// PUT /api/portal/pachtakte/agri – Agri-PV-Bewirtschaftungsnachweis speichern bzw. einreichen
//   { vertragId, id?, daten{jahr,art,kultur,gesamtHa,bewirtschaftetHa,ertrag,einheit,…}, einreichen? }
import { route } from "@/lib/plattform/server/route";
import { pachtakteBackend } from "@/lib/plattform/backend/pachtakte";

export const PUT = route({ rollen: ["flaeche", "landwirt"], limit: "formular" }, async ({ nutzer, body, ip }) => ({
  ok: true,
  nachweis: await pachtakteBackend().agriNachweisSpeichern(nutzer, { vertragId: body.vertragId, id: body.id || null, daten: body.daten || {}, einreichen: body.einreichen === true }, { ip }),
}));
EOF
cat > "$B/rueckbau/[vertragId]/route.js" <<'EOF'
// POST /api/portal/pachtakte/rueckbau/[vertragId] – Eigentümer: Rückbau abnehmen { nach: "abgenommen" }
// oder Mängel melden { nach: "maengel", kommentar }. Übrige Schritte: /api/admin/pachtakte/rueckbau/[vertragId].
import { route } from "@/lib/plattform/server/route";
import { pachtakteBackend } from "@/lib/plattform/backend/pachtakte";

export const POST = route({ rollen: ["flaeche", "landwirt"] }, async ({ nutzer, params, body, ip }) => ({
  ok: true,
  akte: await pachtakteBackend().rueckbauAktion(nutzer, params.vertragId, { ziel: "rueckbau", nach: body.nach, kommentar: body.kommentar }, { ip }),
}));
EOF
cat > "$B/bescheinigung/[jahr]/route.js" <<'EOF'
// GET /api/portal/pachtakte/bescheinigung/[jahr] – Jahresbescheinigung über Pachtzahlungen als PDF (nur eigene
// Gutschriften; Abruf wird protokolliert). `?anzeigen=1` zeigt das PDF im Browser statt Download.
import { route } from "@/lib/plattform/server/route";
import { pachtakteBackend } from "@/lib/plattform/backend/pachtakte";
import { istDemo } from "@/lib/plattform/backend";
import { jahresbescheinigungPdf } from "@/lib/plattform/server/pachtakte-pdf";
import { PlattformFehler } from "@/lib/plattform/fehler";

export const GET = route({ rollen: ["flaeche", "landwirt"] }, async ({ nutzer, params, ip, suche }) => {
  if (!/^\d{4}$/.test(String(params.jahr))) throw new PlattformFehler(404, "Unbekanntes Jahr.");
  const d = await pachtakteBackend().jahresbescheinigungDaten(nutzer, { jahr: Number(params.jahr) }, { ip });
  const pdf = jahresbescheinigungPdf(d, { demo: istDemo() });
  return new Response(pdf, {
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": `${suche.get("anzeigen") === "1" ? "inline" : "attachment"}; filename="Jahresbescheinigung-Pacht-${d.jahr}.pdf"`,
      "Cache-Control": "private, no-store",
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "sandbox",
    },
  });
});
EOF
cat > $A/route.js <<'EOF'
