			z = {"vertragId": vid, "bezeichnung": vt.get("bezeichnung") or b.get("bezugText") or "Pachtvertrag", "land": vt.get("land") or "", "anzahl": 0, "netto": 0, "steuer": 0, "brutto": 0, "bezahlt": 0, "offen": 0, "belege": []}
			zeilen.append(z)
