		z["anzahl"] += 1
		z["netto"] = rund2(z["netto"] + float(b.get("netto") or 0))
		z["steuer"] = rund2(z["steuer"] + float(steuer or 0))
		z["brutto"] = rund2(z["brutto"] + float(b.get("brutto") or 0))
		if b.get("status") == "bezahlt":
