97	/** Finanzmodul-Daten bereitstellen (Seed) und Demo-Akten einmalig ergänzen */
98	async function bereit(n) {
99	  await finanzen.meineAbrechnungen(n); // legt db.finanzen einmalig an (Rechte: nur Anmeldung, Ausgabe hier nicht genutzt)
100	  const db = await lesen();
101	  if ((db.pachtakte?.v || 0) < VERSION) {
102	    await aendern((d) => demoErgaenzen(d));
103	    return lesen();
104	  }
105	  return db;
106	}
107	
108	// ================================================================ Ausgabe
109	
110	function verlaufAus(db, liste = [], { backoffice = false } = {}) {
111	  return (liste || []).map((x) => ({ am: x.am, von: x.von, nach: x.nach, wer: x.wer, text: x.text || "", ...(backoffice && x.nutzerId ? { name: nameVon(db, x.nutzerId) } : {}) }));
112	}
113	
114	function anliegenAus(db, a, { backoffice = false } = {}) {
115	  const pt = vertragVon(db, a.vertragId);
116	  const info = P.anliegenInfo(a.art, pt?.land);
117	  const aus = {
118	    id: a.id, vertragId: a.vertragId, vertrag: pt?.bezeichnung || "", art: a.art, artLabel: info?.label || a.art, status: a.status, statusLabel: P.ANLIEGEN_STATUS[a.status]?.label || a.status,
119	    daten: a.daten, zusammenfassung: P.anliegenZusammenfassung(a), ergebnis: a.ergebnis || null, hinweise: info?.hinweise || [], unterlagen: info?.unterlagen || [],
120	    bearbeitungBis: a.bearbeitungBis || "", erstelltAm: a.erstelltAm, geaendertAm: a.geaendertAm, verlauf: verlaufAus(db, a.verlauf, { backoffice }),
121	    aktionen: P.anliegenAktionen(a.status, backoffice ? "admin" : "eigentuemer").map((u) => ({ nach: u.nach, aktion: u.aktion, pflicht: u.pflicht || [] })),
122	  };
123	  if (backoffice) Object.assign(aus, { kontoId: a.kontoId, konto: nameVon(db, a.kontoId), email: nutzerById(db, a.kontoId)?.email || "", land: pt?.land || "", flaecheId: pt?.flaecheId || null, aufgabeId: a.aufgabeId || null });
124	  return aus;
125	}
126	
127	function agriAus(db, x, { backoffice = false, referenz = null, kategorie = "" } = {}) {
128	  const pt = vertragVon(db, x.vertragId);
129	  const pruefung = P.agriNachweisPruefen(x.daten, { kategorie, referenz: x.daten.art === "betrieb" ? referenz : null, land: pt?.land });
130	  const aus = {
131	    id: x.id, vertragId: x.vertragId, vertrag: pt?.bezeichnung || "", status: x.status, statusLabel: P.AGRI_NACHWEIS_STATUS[x.status]?.label || x.status, daten: x.daten, pruefung,
132	    bearbeitbar: P.agriBearbeitbar(x), erstelltAm: x.erstelltAm, geaendertAm: x.geaendertAm, verlauf: verlaufAus(db, x.verlauf, { backoffice }),
133	  };
134	  if (backoffice) Object.assign(aus, { kontoId: x.kontoId, konto: nameVon(db, x.kontoId), aktionen: P.AGRI_NACHWEIS_UEBERGAENGE.filter((u) => u.wer === "admin" && u.von.includes(x.status)).map((u) => ({ nach: u.nach, aktion: u.aktion, pflicht: u.pflicht || [] })) });
135	  return aus;
136	}
137	
138	const ANGEBOT_FELDER = ["modell", "laufzeitJahre", "laufzeitBeginn", "verlaengerungJahre", "verlaengerung", "vorlaufJahre", "optionsfristJahre", "nichtbau", "kuendigung", "rueckbau", "rueckbauAb", "rueckbauEuro", "dienstbarkeit", "rangruecktritt"];
139	
140	function akteAus(db, pt, { backoffice = false, vertragAusgabe = null } = {}) {
141	  const heute = HEUTE();
142	  const f = flaecheVon(db, pt.flaecheId);
143	  const pa = f?.pachtangebot || null;
144	  const akte = akteVon(db, pt);
145	  const kurz = vertragKurz(pt);
146	  const agriMoeglich = !!(f?.agri || f?.fach?.agri?.kultur);
147	  const nachweiseRoh = sicher(db).agri.filter((x) => x.vertragId === pt.id).sort((a, b) => b.daten.jahr - a.daten.jahr || a.daten.art.localeCompare(b.daten.art));
148	  const kategorie = f?.fach?.agri?.kategorie || "";
149	  const referenz = (einheit) => P.agriReferenz(nachweiseRoh, f?.fach?.agri || null, einheit);
150	  return {
151	    vertrag: { ...(vertragAusgabe || {}), ...kurz, statusLabel: F.PACHTVERTRAG_STATUS[pt.status]?.label || pt.status },
152	    flaeche: f ? { id: f.id, bezeichnung: f.bezeichnung, status: f.status, agri: !!f.agri, land: f.land, kategorie } : null,
153	    angebot: pa ? Object.fromEntries(ANGEBOT_FELDER.filter((k) => pa[k] !== undefined && pa[k] !== null && pa[k] !== "").map((k) => [k, pa[k]])) : null,
154	    fristen: P.vertragsFristen(kurz, pa, { heute }),
155	    rueckbau: { ...akte.rueckbau, statusLabel: P.RUECKBAU_STATUS[akte.rueckbau.status]?.label, text: P.RUECKBAU_STATUS[akte.rueckbau.status]?.text, verlauf: verlaufAus(db, akte.rueckbau.verlauf, { backoffice }), moeglich: P.rueckbauMoeglich(kurz, heute),
156	      aktionen: P.RUECKBAU_UEBERGAENGE.filter((u) => u.wer === (backoffice ? "admin" : "eigentuemer") && u.von.includes(akte.rueckbau.status)).map((u) => ({ nach: u.nach, aktion: u.aktion, pflicht: u.pflicht || [] })) },
157	    sicherheit: { ...akte.sicherheit, statusLabel: P.SICHERHEIT_STATUS[akte.sicherheit.status]?.label, artLabel: P.SICHERHEIT_ARTEN[akte.sicherheit.art] || "", verlauf: verlaufAus(db, akte.sicherheit.verlauf, { backoffice }), hinweise: P.sicherheitHinweise(akte, kurz) },
158	    anliegen: sicher(db).anliegen.filter((a) => a.vertragId === pt.id).sort((a, b) => String(b.erstelltAm).localeCompare(String(a.erstelltAm))).map((a) => anliegenAus(db, a, { backoffice })),
159	    agri: agriMoeglich ? { moeglich: true, kategorie, nachweise: nachweiseRoh.map((x) => agriAus(db, x, { backoffice, referenz: referenz(x.daten.einheit), kategorie })), referenz: referenz("") } : { moeglich: false, nachweise: [] },
160	    historie: (pt.eigentuemerHistorie || []).map((h) => ({ am: h.am, ab: h.ab || "", anlass: h.anlass, ...(backoffice ? { vonName: nameVon(db, h.vonId), nachName: nameVon(db, h.nachId) } : {}) })),
161	    beendbar: (() => { try { return backoffice && pt.status !== "beendet" && P.beendenPruefen(akte); } catch { return false; } })(),
162	  };
163	}
164	
165	// ================================================================ Portal: Eigentümer
166	
167	/** Eigene Pachtakten mit Fristen, Anliegen, Rückbau/Sicherheit, Agri-PV-Nachweisen und Bescheinigungsjahren */
168	export async function meinePachtakte(n) {
169	  eigentuemerRolle(n);
170	  const fin = await finanzen.meineAbrechnungen(n);
171	  const db = await bereit(n);
172	  const aus = new Map((fin.pacht?.vertraege || []).map((x) => [x.id, x]));
173	  const eigene = vertraegeAlle(db).filter((p) => p.eigentuemerId === n.id && p.status !== "entwurf");
174	  const frueher = vertraegeAlle(db).filter((p) => p.eigentuemerId !== n.id && (p.eigentuemerHistorie || []).some((h) => h.vonId === n.id));
175	  // Akten fehlender Verträge einmalig anlegen (nur Schreiben, wenn nötig)
176	  if (eigene.some((p) => !db.pachtakte?.akten?.[p.id])) {
177	    await aendern((d) => { for (const p of eigene) { const pt = vertragVon(d, p.id); if (pt) akteVon(d, pt); } });
178	  }
179	  const db2 = await lesen();
180	  const belege = fin.pacht?.belege || [];
181	  return {
182	    vertraege: eigene.map((p) => akteAus(db2, vertragVon(db2, p.id), { vertragAusgabe: aus.get(p.id) || null })),
183	    frueher: frueher.map((p) => ({ id: p.id, bezeichnung: p.bezeichnung, uebergabe: (p.eigentuemerHistorie || []).filter((h) => h.vonId === n.id).map((h) => ({ am: h.am, ab: h.ab || "", anlass: h.anlass })).pop() || null })),
184	    bescheinigungsJahre: P.bescheinigungsJahre(belege),
